    client.estate = EstateApi(client)  # type: ignore[attr-defined]
    client.power = PowerApi(client)  # type: ignore[attr-defined]
    client.market = MarketApi(client)  # type: ignore[attr-defined]
    client.feed = FeedApi(client)  # type: ignore[attr-defined]
