def _async_attach(client: AsyncSatelit) -> None:
    """Sets the namespaces on a client."""
    client.rates = AsyncRatesApi(client)  # type: ignore[attr-defined]
    client.fuel = AsyncFuelApi(client)  # type: ignore[attr-defined]
    client.tariffs = AsyncTariffsApi(client)  # type: ignore[attr-defined]
    client.indexes = AsyncIndexesApi(client)  # type: ignore[attr-defined]
    client.law = AsyncLawApi(client)  # type: ignore[attr-defined]
    client.news = AsyncNewsApi(client)  # type: ignore[attr-defined]
    client.places = AsyncPlacesApi(client)  # type: ignore[attr-defined]
    client.recipes = AsyncRecipesApi(client)  # type: ignore[attr-defined]
    client.prices = AsyncPricesApi(client)  # type: ignore[attr-defined]
    client.deals = AsyncDealsApi(client)  # type: ignore[attr-defined]
    client.tours = AsyncToursApi(client)  # type: ignore[attr-defined]
    client.flights = AsyncFlightsApi(client)  # type: ignore[attr-defined]
    client.rest = AsyncRestApi(client)  # type: ignore[attr-defined]
    client.estate = AsyncEstateApi(client)  # type: ignore[attr-defined]
    client.power = AsyncPowerApi(client)  # type: ignore[attr-defined]
    client.market = AsyncMarketApi(client)  # type: ignore[attr-defined]
    client.feed = AsyncFeedApi(client)  # type: ignore[attr-defined]
    client.jokes = AsyncJokesApi(client)  # type: ignore[attr-defined]
    client.courts = AsyncCourtsApi(client)  # type: ignore[attr-defined]
    client.citizenship = AsyncCitizenshipApi(client)  # type: ignore[attr-defined]
    client.companies = AsyncCompaniesApi(client)  # type: ignore[attr-defined]
    client.delivery = AsyncDeliveryApi(client)  # type: ignore[attr-defined]
    client.insurance = AsyncInsuranceApi(client)  # type: ignore[attr-defined]
    client.geo = AsyncGeoApi(client)  # type: ignore[attr-defined]
    client.catalog = AsyncCatalogApi(client)  # type: ignore[attr-defined]
    client.movies = AsyncMoviesApi(client)  # type: ignore[attr-defined]


